#!/bin/sh
network_tools_menu(){ while :; do c=$(ui_menu 'Network diagnostics and tools' 'Connectivity, DNS, HTTP, TLS, proxy, and socket tools.' summary 'Network summary' dns 'DNS diagnostics' http 'HTTP diagnostics' tls 'TLS certificate viewer' ports 'Listening ports' routes 'Routes and interfaces' proxy 'Configure proxy variables' server 'Start temporary HTTP server' sshdiag 'SSH diagnostic collection' mirror 'Repository latency test' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in summary) run_capture Network sh -c 'ip addr 2>/dev/null || ifconfig -a 2>/dev/null; printf "\nresolv.conf:\n"; cat /etc/resolv.conf; printf "\nhosts:\n"; cat /etc/hosts';; dns) h=$(ui_input DNS 'Hostname' example.com) || continue; run_capture DNS sh -c "getent hosts '$h' 2>/dev/null || nslookup '$h' 2>/dev/null || drill '$h' 2>/dev/null";; http) u=$(ui_input HTTP 'URL' https://example.com) || continue; run_capture HTTP sh -c "curl -IL --max-time 15 '$u' 2>/dev/null || wget -S --spider '$u'";; tls) h=$(ui_input TLS 'host:port' example.com:443) || continue; host=${h%:*}; run_capture TLS sh -c "echo | openssl s_client -connect '$h' -servername '$host' 2>/dev/null | openssl x509 -noout -subject -issuer -dates -fingerprint";; ports) run_capture Ports sh -c 'ss -lntup 2>/dev/null || netstat -lntup 2>/dev/null';; routes) run_capture Routes sh -c 'ip route 2>/dev/null; ip -6 route 2>/dev/null; ip link 2>/dev/null';; proxy) v=$(ui_input Proxy 'HTTP(S) proxy URL; blank disables' '') || continue; [ -n "$v" ] && body="export http_proxy='$v'\nexport https_proxy='$v'\nexport HTTP_PROXY='$v'\nexport HTTPS_PROXY='$v'" || body='unset http_proxy https_proxy HTTP_PROXY HTTPS_PROXY'; replace_block "$CURRENT_HOME/.profile" proxy "$body";; server) d=$(ui_input Server 'Directory' .) || continue; p=$(ui_input Server 'Port' 8000) || continue; have python3 && (cd "$d" && python3 -m http.server "$p") || ui_msg Server 'python3 is required.';; sshdiag) run_capture SSH sh -c 'ssh -V; ssh -G localhost 2>/dev/null | head -100; test -f /etc/ssh/sshd_config && sshd -T 2>&1 | head -100 || true';; mirror) run_capture Mirrors pkg_update;; back) return;; esac; done; }
